ation\\" style=\\"vertical-align:top;\\" width=\\"100%\\"\\n      >\\n        <tbody>\\n          \\n              <tr>\\n                <td\\n                   align=\\"center\\" style=\\"font-size:0px;padding:10px 25px;word-break:break-word;\\"\\n                >\\n                  \\n      <table\\n         border=\\"0\\" cellpadding=\\"0\\" cellspacing=\\"0\\" role=\\"presentation\\" style=\\"border-collapse:separate;line-height:100%;\\"\\n      >\\n        <tbody>\\n          <tr>\\n            <td\\n               align=\\"center\\" bgcolor=\\"#163986\\" role=\\"presentation\\" style=\\"border:none;border-radius:6px;cursor:auto;mso-padding-alt:10px 25px;background:#163986;\\" valign=\\"middle\\"\\n            >\\n              <a\\n                 href=\\"{{url}}\\" style=\\"display:inline-block;background:#163986;color:#ffffff;font-family:Poppins, Arial, Helvetica, sans-serif;font-size:13px;font-weight:600;line-height:120%;margin:0;text-decoration:none;text-transform:none;padding:10px 25px;mso-padding-alt:0px;border-radius:6px;\\" target=\\"_blank\\"\\n              >\\n                Recuperar mi contraseña\\n              </a>\\n            </td>\\n          </tr>\\n        </tbody>\\n      </table>\\n    \\n                </td>\\n              </tr>\\n            \\n        </tbody>\\n      </table>\\n    \\n      </div>\\n    \\n          <!--[if mso | IE]></td></tr></table><![endif]-->\\n              </td>\\n            </tr>\\n          </tbody>\\n        </table>\\n        \\n      </div>\\n    \\n      \\n      <!--[if mso | IE]></td></tr></table><table align=\\"center\\" border=\\"0\\" cellpadding=\\"0\\" cellspacing=\\"0\\" class=\\"\\" role=\\"presentation\\" style=\\"width:600px;\\" width=\\"600\\" bgcolor=\\"#F4F5F7\\" ><tr><td style=\\"line-height:0px;font-size:0px;mso-line-height-rule:exactly;\\"><![endif]-->\\n    \\n      \\n      <div  style=\\"background:#F4F5F7;background-color:#F4F5F7;margin:0px auto;max-width:600px;\\">\\n        \\n        <table\\n           align=\\"center\\" border=\\"0\\" cellpadding=\\"0\\" cellspacing=\\"0\\" role=\\"presentation\\" style=\\"background:#F4F5F7;background-color:#F4F5F7;width:100%;\\"\\n        >\\n          <tbody>\\n            <tr>\\n              <td\\n                 style=\\"direction:ltr;font-size:0px;padding:20px 24px;text-align:center;\\"\\n              >\\n                <!--[if mso | IE]><table role=\\"presentation\\" border=\\"0\\" cellpadding=\\"0\\" cellspacing=\\"0\\"><tr><td class=\\"\\" style=\\"vertical-align:top;width:552px;\\" ><![endif]-->\\n            \\n      <div\\n         class=\\"mj-column-per-100 mj-outlook-group-fix\\" style=\\"font-size:0px;text-align:left;direction:ltr;display:inline-block;vertical-align:top;width:100%;\\"\\n      >\\n        \\n      <table\\n         border=\\"0\\" cellpadding=\\"0\\" cellspacing=\\"0\\" role=\\"presentation\\" style=\\"vertical-align:top;\\" width=\\"100%\\"\\n      >\\n        <tbody>\\n          \\n              <tr>\\n                <td\\n                   align=\\"center\\" style=\\"font-size:0px;padding:10px 25px;word-break:break-word;\\"\\n                >\\n                  \\n      <div\\n         style=\\"font-family:Poppins, Arial, Helvetica, sans-serif;font-size:12px;line-height:1.6;text-align:center;color:#8A8D98;\\"\\n      >Bial Regional Academy<br/>Este correo se envió automáticamente, por favor no responda.</div>\\n    \\n                </td>\\n              </tr>\\n            \\n        </tbody>\\n      </table>\\n    \\n      </div>\\n    \\n          <!--[if mso | IE]></td></tr></table><![endif]-->\\n              </td>\\n            </tr>\\n          </tbody>\\n        </table>\\n        \\n      </div>\\n    \\n      \\n      <!--[if mso | IE]></td></tr></table><![endif]-->\\n    \\n    \\n      </div>\\n    \\n  </body>\\n</html>\\n  "', 4, 1, 0 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `email_template` WHERE `name_key` = 'recover_4');
INSERT INTO `email_template` (`name`, `name_key`, `subject`, `design`, `html`, `id_lang`, `is_active`, `can_delete`) SELECT 'Recover password', 'recover_5', 'Recover your password', '{"editor":"grapes","mjml":"<mjml>\\n  <mj-head>\\n    <mj-font name=\\"Poppins\\" href=\\"https://fonts.googleapis.com/css?family=Poppins:300,400,500,600,700\\"></mj-font>\\n    <mj-attributes>\\n      <mj-all font-family=\\"Poppins, Arial, Helvetica, sans-serif\\"></mj-all>\\n      <mj-text font-size=\\"15px\\" color=\\"#333333\\" line-height=\\"1.6\\"></mj-text>\\n    </mj-attributes>\\n  </mj-head>\\n  <mj-body background-color=\\"#F4F5F7\\" width=\\"600px\\">\\n    <mj-section background-color=\\"#163986\\" padding=\\"20px 24px\\"><mj-column><mj-text font-family=\\"Ryker, Poppins, Arial, Helvetica, sans-serif\\" font-size=\\"20px\\" font-weight=\\"700\\" color=\\"#ffffff\\" padding=\\"0\\">Bial Regional Academy</mj-text></mj-column></mj-section>\\n    <mj-section background-color=\\"#ffffff\\" padding=\\"28px 24px 8px\\"><mj-column>\\n        <mj-text font-family=\\"Ryker, Poppins, Arial, Helvetica, sans-serif\\" font-size=\\"22px\\" font-weight=\\"700\\" color=\\"#163986\\">Hello {{name}},</mj-text>\\n        <mj-text>We received a request to recover the password of your Bial Regional Academy account.</mj-text>\\n        <mj-text>Enter this code on the recovery page to choose a new password:</mj-text>\\n    </mj-column></mj-section>\\n    <mj-section background-color=\\"#ffffff\\" padding=\\"0 24px 12px\\"><mj-column background-color=\\"#F6F7FB\\" border-radius=\\"10px\\" padding=\\"14px 18px\\"><mj-text align=\\"center\\" font-size=\\"30px\\" font-weight=\\"700\\" letter-spacing=\\"4px\\" color=\\"#163986\\">{{code}}</mj-text></mj-column></mj-section>\\n    <mj-section background-color=\\"#ffffff\\" padding=\\"0 24px 28px\\"><mj-column><mj-button background-color=\\"#163986\\" color=\\"#ffffff\\" border-radius=\\"6px\\" font-weight=\\"600\\" href=\\"{{url}}\\">Recover my password</mj-button></mj-column></mj-section>\\n    <mj-section background-color=\\"#F4F5F7\\" padding=\\"20px 24px\\"><mj-column><mj-text align=\\"center\\" font-size=\\"12px\\" color=\\"#8A8D98\\" line-height=\\"1.6\\">Bial Regional Academy<br/>This e-mail was sent automatically, please do not reply.</mj-text></mj-column></mj-section>\\n  </mj-body>\\n</mjml>"}', '"<!doctype html>\\n<html lang=\\"und\\" dir=\\"auto\\" xmlns=\\"http://www.w3.org/1999/xhtml\\" xmlns:v=\\"urn:schemas-microsoft-com:vml\\" xmlns:o=\\"urn:schemas-microsoft-com:office:office\\">\\n  <head>\\n    <title></title>\\n    <!--[if !mso]><!-->\\n    <meta http-equiv=\\"X-UA-Compatible\\" content=\\"IE=edge\\">\\n    <!--<![endif]-->\\n    <meta http-equiv=\\"Content-Type\\" content=\\"text/html; charset=UTF-8\\">\\n    <meta name=\\"viewport\\" content=\\"width=device-width, initial-scale=1\\">\\n    <style type=\\"text/css\\">\\n      #outlook a { padding:0; }\\n      body { margin:0;padding:0;-webkit-text-size-adjust:100%;-ms-text-size-adjust:100%; }\\n      table, td { border-collapse:collapse;mso-table-lspace:0pt;mso-table-rspace:0pt; }\\n      img { border:0;height:auto;line-height:100%; outline:none;text-decoration:none;-ms-interpolation-mode:bicubic; }\\n      p { display:block;margin:13px 0; }\\n    </style>\\n    <!--[if mso]>\\n    <noscript>\\n    <xml>\\n    <o:OfficeDocumentSettings>\\n      <o:AllowPNG/>\\n      <o:PixelsPerInch>96</o:PixelsPerInch>\\n    </o:OfficeDocumentSettings>\\n    </xml>\\n    </noscript>\\n    <![endif]-->\\n    <!--[if lte mso 11]>\\n    <style type=\\"text/css\\">\\n      .mj-outlook-group-fix { width:100% !important; }\\n    </style>\\n    <![endif]-->\\n    \\n      <!--[if !mso]><!-->\\n        <link href=\\"https://fonts.googleapis.com/css?family=Poppins:300,400,500,600,700\\" rel=\\"stylesheet\\" type=\\"text/css\\">\\n        <style type=\\"text/css\\">\\n          @import url(https://fonts.googleapis.com/css?family=Poppins:300,400,500,600,700);\\n        